// The theme's pictures (docs/19 §5.1), drawn with Canvas::art: the status bar's head (palette
// entries, gen/icons_gen.h; 0 clear) and Mando's key poses (4 bits a pixel in his 15
// colours, gen/mando46_gen.h and mando64_gen.h; 0 clear). All const arrays generated by
// tools/theme, in flash. Pure.
#pragma once

#include <cstdint>

#include "canvas.h"
#include "gen/art_ids.h"

namespace cpa {

enum class ArtId : uint8_t {
  Head,     // the status bar's 11 x 9 Mando head: linked to the Mac
  Mando46,  // 26 x 46: frame k of kMando46 (gen/art_ids.h) is Mando46 + k
  Mando64 = Mando46 + theme::gen::kMando46Frames,  // 36 x 64: frame k is Mando64 + k
  Count = Mando64 + theme::gen::kMando64Frames,
};

namespace theme {

struct ArtView {
  const uint8_t* px = nullptr;
  int16_t w = 0;
  int16_t h = 0;
  bool mando4 = false;  // 4 bits a pixel in Mando's colours (theme_raster.h Nibbles)
};

ArtView art_of(ArtId id);  // w == 0 for an id the theme does not have

}  // namespace theme
}  // namespace cpa
